    "officialAnswer": "A",
    "officialAnswerSource": "UPSC Civil Services CSAT (GS Paper II) 2026 Official Answer Key",
    "solution": "Official Mathematical Analysis for Q30:\nWord: IKSHOVIA (8 letters: I, K, S, H, O, V, I, A).\nVowels: I, O, I, A (4 vowels, note letter 'I' appears 2 times).\nConsonants: K, S, H, V (4 consonants).\nTreat the 4 vowels as 1 single block: Total entities = 4 consonants + 1 block = 5 entities.\nThese 5 entities can be arranged in 5! = 120 ways.\nWithin the vowel block (I, O, I, A), the 4 vowels can be arranged among themselves in 4! / 2! = 24 / 2 = 12 ways.\nTotal distinct permutations = 120 * 12 = 1440.\nHence Option (A) is the correct answer.",
    "solutionEn": "Official Mathematical Analysis for Q30:\nWord: IKSHOVIA (8 letters: I, K, S, H, O, V, I, A).\nVowels: I, O, I, A (4 vowels, note letter 'I' appears 2 times).\nConsonants: K, S, H, V (4 consonants).\nTreat the 4 vowels as 1 single block: Total entities = 4 consonants + 1 block = 5 entities.\nThese 5 entities can be arranged in 5! = 120 ways.\nWithin the vowel block (I, O, I, A), the 4 vowels can be arranged among themselves in 4! / 2! = 24 / 2 = 12 ways.\nTotal distinct permutations = 120 * 12 = 1440.\nHence Option (A) is the correct answer.",
    "solutionHi": "प्रश्न 30 का आधिकारिक गणितीय हल:\nशब्द: IKSHOVIA (कुल 8 अक्षर)\nस्वर: I, O, I, A (4 स्वर, 'I' दो बार आता है)\nव्यंजन: K, S, H, V (4 व्यंजन)\n4 स्वरों को एक ब्लॉक मानने पर कुल वस्तुएं = 4 व्यंजन + 1 ब्लॉक = 5 इकाइयां\n5 इकाइयों को व्यवस्थित करने के तरीके = 5! = 120\nस्वर ब्लॉक के अंदर अक्षरों के विन्यास = 4! / 2! = 24 / 2 = 12\nकुल विन्यास = 120 * 12 = 1440\nअतः विकल्प (A) सही उत्तर है।",
    "solutionSource": "IKSHOVIA CSAT Editorial & Analytical Validation Standard",
