    "questionText": "Q35 (2026 CSAT Paper-II).\n\nConsider the following two statements and two conclusions:\nStatements:\n1. All satellites equipped with quantum transceivers are highly secure.\n2. Some defense observation platforms are satellites equipped with quantum transceivers.\nConclusions:\nI. Some defense observation platforms are highly secure.\nII. No highly secure platform is a non-satellite.\nWhich of the conclusions logically follow(s) from the given statements?",
    "questionEn": "Q35 (2026 CSAT Paper-II).\n\nConsider the following two statements and two conclusions:\nStatements:\n1. All satellites equipped with quantum transceivers are highly secure.\n2. Some defense observation platforms are satellites equipped with quantum transceivers.\nConclusions:\nI. Some defense observation platforms are highly secure.\nII. No highly secure platform is a non-satellite.\nWhich of the conclusions logically follow(s) from the given statements?",
    "questionHi": "प्रश्न 35 (2026 सिविल सेवा CSAT प्रश्नपत्र-II)।\n\nनिम्नलिखित दो कथनों और दो निष्कर्षों पर विचार कीजिए:\nकथन:\n1. क्वांटम ट्रांसीवर से लैस सभी उपग्रह अत्यधिक सुरक्षित हैं।\n2. कुछ रक्षा अवलोकन प्लेटफॉर्म क्वांटम ट्रांसीवर से लैस उपग्रह हैं।\nनिष्कर्ष:\nI. कुछ रक्षा अवलोकन प्लेटफॉर्म अत्यधिक सुरक्षित हैं।\nII. कोई भी अत्यधिक सुरक्षित प्लेटफॉर्म गैर-उपग्रह नहीं है।\nदिए गए कथनों में से कौन सा/से निष्कर्ष तार्किक रूप से निकलता है/निकलते हैं?",
