    "questionText": "Q49 (2026 CSAT Paper-II).\n\nRead the following passage and answer the question:\n\"Technological sovereignty in artificial intelligence cannot be achieved through algorithmic adoption alone; it requires deep-tier semiconductor foundries, indigenous training datasets, and robust data privacy architectures. Nations that rely entirely on foreign compute infrastructures risk structural vulnerabilities during geopolitical realignments.\"\n\nBased on the above passage, which of the following is the most crucial assumption?",
