    "questionText": "Q58 (2026 CSAT Paper-II).\n\nIn how many distinct ways can the letters of the word \"IKSHOVIA\" be arranged such that all the vowels always appear together in a consecutive block?",
    "questionEn": "Q58 (2026 CSAT Paper-II).\n\nIn how many distinct ways can the letters of the word \"IKSHOVIA\" be arranged such that all the vowels always appear together in a consecutive block?",
    "questionHi": "प्रश्न 58 (2026 सिविल सेवा CSAT प्रश्नपत्र-II)।\n\nशब्द \"IKSHOVIA\" के अक्षरों को कितने भिन्न तरीकों से व्यवस्थित किया जा सकता है ताकि सभी स्वर (vowels) हमेशा एक साथ एक क्रमागत समूह में आएं?",
