    "questionHi": "प्रश्न 77 (2026 सिविल सेवा CSAT प्रश्नपत्र-II)।\n\nनिम्नलिखित गद्यांश को पढ़िए और प्रश्न का उत्तर दीजिए:\n\"कृत्रिम बुद्धिमत्ता (AI) में तकनीकी संप्रभुता केवल एल्गोरिथम अपनाने से प्राप्त नहीं की जा सकती; इसके लिए गहन अर्धचालक (सेमीकंडक्टर) फाउंड्री, स्वदेशी प्रशिक्षण डेटासेट और मजबूत डेटा गोपनीयता संरचनाओं की आवश्यकता होती है। जो राष्ट्र पूरी तरह से विदेशी कंप्यूटिंग बुनियादी ढांचे पर निर्भर हैं, वे भू-राजनीतिक वास्तविकताओं के दौरान संरचनात्मक कमजोरियों का जोखिम उठाते हैं।\"\n\nउपर्युक्त गद्यांश के आधार पर, निम्नलिखित में से कौन सी सबसे महत्वपूर्ण पूर्वधारणा है?",
