    "questionHi": "प्रश्न 78 (2026 सिविल सेवा CSAT प्रश्नपत्र-II)।\n\nशब्द \"IKSHOVIA\" के अक्षरों को कितने भिन्न तरीकों से व्यवस्थित किया जा सकता है ताकि सभी स्वर (vowels) हमेशा एक साथ एक क्रमागत समूह में आएं?",
